import { Container, Row, Col } from "react-bootstrap";
import "../App.css";
import moon from "../assets/img/moon.png";
import astronaut from "../assets/img/astronaut.png";

export const Education = () => {
  const education = [
    {
      institute: "Acharya Institute of Technology",
      degree: "Master of Computer Applications (MCA)",
      year: "2025 – 2027"
    },
    {
      institute: "KLE Society’s Shri Shivayogi Murughendra Swamiji BCA College",
      degree: "Bachelor of Computer Applications (BCA)",
      year: "2022 – 2025"
    },
    {
      institute: "Sai Niketan PU Science College",
      degree: "PUC – Science",
      year: "2020 – 2022"
    },
    {
      institute: "Swami Vivekanand International Public School (CBSE)",
      degree: "Schooling",
      year: "2009 – 2020"
    }
  ];

  return (
    <section className="education-section" id="education">
      <img src={moon} className="edu-moon" alt="moon" />
      <img src={astronaut} className="edu-astronaut" alt="astronaut" />

      <Container>
        <Row>
          <Col>
            <h2 className="edu-title">EDUCATION</h2>
          </Col>
        </Row>

        <Row className="edu-cards">
          {education.map((edu, index) => (
            <Col md={6} key={index}>
              <div className="edu-glass-card">
                <h4>{edu.institute}</h4>
                <p>{edu.degree}</p>
                <span>{edu.year}</span>
              </div>
            </Col>
          ))}
        </Row>
      </Container>
    </section>
  );
};
